function zpiz.UseHungermod()
	if DarkRP and DarkRP.disabledDefaults and DarkRP.disabledDefaults["modules"] and DarkRP.disabledDefaults["modules"]["hungermod"] ~= true then
		return true
	else
		return false
	end
end
